	@Test
	void rejectsUnknownPositionBitsAtEveryEntryPoint(@TempDir File directory) throws Exception {
		try (TestValueStore store = store(directory, 64)) {
			long id = persist(store, "invalid-position");
			LmdbValue value = store.createIRI("urn:invalid-position");
			for (int mask : new int[] { -1, 16, 32, Integer.MIN_VALUE }) {
				assertThrows(IllegalArgumentException.class, () -> lazy(store, id, mask));
				assertThrows(IllegalArgumentException.class, () -> getValue(store, id, mask));
				assertThrows(IllegalArgumentException.class, () -> cached(store, id, mask));
				assertThrows(IllegalArgumentException.class, () -> store.cacheValue(id, value, mask));
				assertThrows(IllegalArgumentException.class, () -> store.resolveValue(id, value, mask));
				assertThrows(IllegalArgumentException.class, () -> ValuePosition.cacheBank(mask));
			}
		}
	}

	@Test
	void concurrentResolutionKeepsEachBankCorrect(@TempDir File directory) throws Exception {
		try (TestValueStore store = store(directory, 64);
				var executor = Executors.newFixedThreadPool(5)) {
			long id = persist(store, "concurrent-position");
			List<Callable<Void>> jobs = new ArrayList<>();
			for (int mask : MASKS) {
				jobs.add(() -> {
					for (int i = 0; i < 100; i++) {
						assertEquals("urn:concurrent-position", lazy(store, id, mask).stringValue());
					}
					return null;
				});
			}
			for (var result : executor.invokeAll(jobs)) {
				result.get();
			}
			for (int mask : MASKS) {
				assertEquals("urn:concurrent-position", cached(store, id, mask).stringValue());
			}
		}
	}

	private static TestValueStore store(File directory, int capacity) throws Exception {
		return new TestValueStore(directory, capacity);
	}

	private static final class TestValueStore extends ValueStore implements AutoCloseable {

		private int readTransactionCount;

		TestValueStore(File directory, int capacity) throws Exception {
			super(directory, new LmdbStoreConfig().setValueCacheSize(capacity));
		}

		@Override
		<T> T readTransaction(long env, LmdbUtil.Transaction<T> transaction) throws IOException {
			readTransactionCount++;
			return super.readTransaction(env, transaction);
		}
	}

	private static long persist(ValueStore store, String label) throws Exception {
		store.startTransaction(true);
		long id = store.storeValue(store.createIRI("urn:" + label));
		store.commit();
		store.clearCaches();
		return id;
	}

	private static MapBindingSet row(LmdbValue value) {
		MapBindingSet row = new MapBindingSet();
		row.addBinding("v", value);
		return row;
	}

	private static LmdbValue lazy(ValueStore store, long id, int mask) throws Exception {
		return store.getLazyValue(id, mask);
	}

	private static LmdbValue getValue(ValueStore store, long id, int mask) throws Exception {
		return store.getValue(id, mask);
	}

	private static LmdbValue cached(ValueStore store, long id, int mask) throws Exception {
		return store.cachedValue(id, mask);
	}

